28	/**
29	 * The claims on a sheet: added to a person and edited (amount, date, note). A claim given no date
30	 * takes the sheet's today. A claim starts as DRAFT and moves through its statuses (see
31	 * {@link ClaimStatus}); a change its status does not allow is refused. Only a DRAFT can be edited:
32	 * to change an open claim, void it and add a new one. Settling a claim fixes its
33	 * due at the rate its person's grade has then for the claim's date; an open claim's due stays live.
34	 * A claim records who opened it, and that user cannot settle it (four eyes). A claim bound by its
35	 * person's last statement keeps the figure it had then, and settling it fixes that figure. No claim
36	 * dated inside a closed period can be added, edited (to or from such a date) or change status. No
37	 * claim can be added or edited to a date after its person's retirement date. A clerk settles a claim
38	 * only when its figure is at or below the sheet's clerk limit (a claim with no figure is within any
39	 * limit); a clerk settling one above it makes it PENDING instead. A steward settles any claim, and
40	 * approves a PENDING claim (SETTLED, its due fixed then) or rejects it with a reason (back to OPEN);
41	 * the user who opened a claim cannot approve it. A PENDING claim is not bound by a statement: it
42	 * shows its live figure, and is bound again by the last statement once rejected. A claim's live due is never below the sheet's floor. An
43	 * overdue claim's due gains a late charge on top of its figure (see {@link LateCharge}); a statement
44	 * binds only the figure under it, and settling fixes the charge into the settled due. A claim with
45	 * a negative amount is a correction: it is allowed only when it names, by number, a SETTLED claim
46	 * of the same person that it corrects. Its due has no floor and no late charge. A steward can move
47	 * a DRAFT, OPEN or PENDING claim to another person: it keeps its number and date, loses any figure
48	 * a statement bound it to, and is listed as its new person's newest claim. A steward can re-settle
49	 * a SETTLED claim: its due is fixed again at the figure it would have today as an open claim bound
50	 * by no statement (today's rates, grades, floor and late charge). An OPEN claim can be deferred to
51	 * a date after the sheet's today: until the sheet's today reaches it the claim counts in no total,
52	 * is not overdue, cannot be settled and is left unbound by a statement; from then on it is an OPEN
53	 * claim like any other. A claim has a proofs count, raised by one at a time while it is not SETTLED
54	 * or VOID. A claim whose figure is above the proof threshold in force on its date cannot be settled
55	 * or approved while it has no proofs: that is refused before the clerk limit is considered.
56	 * Who may open, settle, void or move a claim is the sheet's permission matrix (see
57	 * {@link Sheet#permits}): an action the user's role may not take is refused (403).
58	 */
59	@Service
60	public class ClaimService {
61	
62	    private final ClaimRepository claims;
63	    private final PersonRepository people;
64	    private final RateRepository rates;
65	    private final SheetService sheets;
66	    private final Audit audit;
67	    private final RollupService rollup;
68	    private final PeriodService periods;
69	    private final RoleService roles;
70	
71	    public ClaimService(ClaimRepository claims, PersonRepository people, RateRepository rates, SheetService sheets,
72	            Audit audit, RollupService rollup, PeriodService periods, RoleService roles) {
73	        this.roles = roles;
74	        this.rollup = rollup;
75	        this.periods = periods;
76	        this.claims = claims;
77	        this.people = people;
78	        this.rates = rates;
79	        this.sheets = sheets;
80	        this.audit = audit;
81	    }
82	
83	    /**
84	     * A claim's figure under any late charge: the due fixed when settled, else the one bound by a
85	     * statement (not while PENDING), else the live due; null when it has none.
86	     */
87	    public BigDecimal figure(String sheetId, Person person, Claim claim) {
88	        if (claim.getStatus() == ClaimStatus.SETTLED) {
89	            return claim.getSettledDue();
90	        }
91	        return claim.isStated() && claim.getStatus() != ClaimStatus.PENDING ? claim.getStatedDue()
92	                : due(sheetId, person, claim);
93	    }
94	
95	    /** A claim's figure with its late charge on the sheet's today added on top; null when it has none. */
96	    public BigDecimal charged(String sheetId, Person person, Claim claim) {
97	        return LateCharge.withCharge(sheets.sheet(sheetId), claim, figure(sheetId, person, claim));
98	    }
99	
100	    @Transactional(readOnly = true)
101	    public List<Claim> list(String sheetId) {
102	        return claims.findBySheetIdOrderByListedDesc(sheetId);
103	    }
104	
105	    @Transactional
106	    public Claim add(String sheetId, String user, long personId, BigDecimal amount, LocalDate date, String note,
107	            String corrects) {
108	        roles.refuseViewer(sheetId, user);
109	        Person person = person(sheetId, personId);
110	        LocalDate dated = dateOrToday(sheetId, date);
111	        periods.refuseIfClosed(sheetId, dated);
112	        refuseIfRetired(person, dated);
113	        String corrected = corrected(sheetId, personId, amount, corrects);
114	        RollupService.Snapshot before = rollup.snapshot(sheetId);
115	        Claim claim = new Claim(sheetId, personId, amount, dated,
116	                dated.plusDays(sheets.sheet(sheetId).termsFor(person.gradeOn(dated), dated)), note, corrected);
117	        logStatus(sheetId, user, person, claim);
118	        Claim added = claims.saveAndFlush(claim);
119	        audit.recordOnCommit(record("CLAIM_ADDED", sheetId, user, person, added));
120	        rollup.recordChanges(sheetId, user, before);
121	        return added;
122	    }
123	
124	    @Transactional
125	    public Claim update(String sheetId, String user, long id, BigDecimal amount, LocalDate date, String note,
126	            String corrects) {
127	        roles.refuseViewer(sheetId, user);
128	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
129	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet."));
130	        if (claim.getStatus() != ClaimStatus.DRAFT) {
131	            throw new ResponseStatusException(HttpStatus.CONFLICT,
132	                    "A " + claim.getStatus() + " claim cannot be edited.");
133	        }
134	        LocalDate dated = dateOrToday(sheetId, date);
135	        periods.refuseIfClosed(sheetId, claim.getDate());
136	        periods.refuseIfClosed(sheetId, dated);
137	        refuseIfRetired(person(sheetId, claim.getPersonId()), dated);
138	        String corrected = corrected(sheetId, claim.getPersonId(), amount, corrects);
139	        RollupService.Snapshot before = rollup.snapshot(sheetId);
140	        claim.setAmount(amount);
141	        claim.setDate(dated);
142	        claim.setNote(note);
143	        claim.setCorrects(corrected);
144	        Claim saved = claims.saveAndFlush(claim);
145	        audit.recordOnCommit(record("CLAIM_EDITED", sheetId, user, person(sheetId, saved.getPersonId()), saved));
146	        rollup.recordChanges(sheetId, user, before);
147	        return saved;
148	    }
149	
150	    /**
151	     * Move a claim to a new status, refused (409) when its current status does not allow it,
152	     * refused (403) when the user who opened it tries to settle it, and refused (422) settling a
153	     * claim above the proof threshold with no proofs. A clerk settling one whose
154	     * figure is above the sheet's clerk limit makes it PENDING instead.
155	     */
156	    @Transactional
157	    public Claim changeStatus(String sheetId, String user, long id, ClaimStatus next) {
158	        return changeStatus(sheetId, user, id, next, null, false);
159	    }
160	
161	    /**
162	     * Approve a PENDING claim: it becomes SETTLED, its due fixed at its live figure with its late
163	     * charge on the sheet's today. Refused (409) when not PENDING, and (403) for a clerk or the
164	     * user who opened it.
165	     */
166	    @Transactional
167	    public Claim approve(String sheetId, String user, long id) {
168	        return changeStatus(sheetId, user, id, ClaimStatus.SETTLED, null, true);
169	    }
170	
171	    /**
172	     * Reject a PENDING claim with a reason: it is OPEN again, bound again by the last statement if
173	     * that statement included it. Refused (409) when not PENDING, and (403) for a clerk.
174	     */
175	    @Transactional
176	    public Claim reject(String sheetId, String user, long id, String reason) {
177	        return changeStatus(sheetId, user, id, ClaimStatus.OPEN, reason, true);
178	    }
179	
180	    /** Move a claim to a new status; {@code review} for a steward's approval or rejection of a PENDING claim. */
181	    private Claim changeStatus(String sheetId, String user, long id, ClaimStatus next, String reason,
182	            boolean review) {
183	        roles.refuseViewer(sheetId, user);
184	        if (!review) {
185	            roles.refuseUnlessPermitted(sheetId, user, switch (next) {
186	                case OPEN -> "open";
187	                case SETTLED -> "settle";
188	                case VOID -> "void";
189	                default -> throw new IllegalStateException();
190	            });
191	        }
192	        // lock the sheet's numbering before reading the claim, so a claim is opened (and numbered) once
193	        if (next == ClaimStatus.OPEN) {
194	            sheets.lock(sheetId);
195	        }
196	        RollupService.Snapshot before = rollup.snapshot(sheetId);
197	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
198	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet."));
199	        ClaimStatus was = claim.getStatus();
200	        // only a steward's review moves a PENDING claim on, other than voiding it
201	        if (!was.canBecome(next) || (next != ClaimStatus.VOID && review != (was == ClaimStatus.PENDING))) {
202	            throw new ResponseStatusException(HttpStatus.CONFLICT,
203	                    "A " + claim.getStatus() + " claim cannot become " + next + ".");
204	        }
205	        periods.refuseIfClosed(sheetId, claim.getDate());
206	        if (next == ClaimStatus.SETTLED && claim.isDeferredOn(sheets.today(sheetId))) {
207	            throw new ResponseStatusException(HttpStatus.CONFLICT,
208	                    "A claim deferred until " + claim.getDeferredUntil() + " cannot be settled before then.");
209	        }
210	        if (next == ClaimStatus.SETTLED && user.equals(claim.getOpenedBy())) {
211	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
212	                    "The user who opened a claim cannot " + (review ? "approve" : "settle") + " it.");
213	        }
214	        if (review && !isSteward(sheetId, user)) {
215	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
216	                    "Only a steward can approve or reject a PENDING claim.");
217	        }
218	        Person person = person(sheetId, claim.getPersonId());
219	        // settling fixes the figure with its late charge as it stands on the sheet's today (a
220	        // PENDING claim's figure is live)
221	        BigDecimal settling = next == ClaimStatus.SETTLED ? charged(sheetId, person, claim) : null;
222	        if (next == ClaimStatus.SETTLED && needsProof(sheetId, claim, settling)) {
223	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,
224	                    "A claim due above the proof threshold cannot be " + (review ? "approved" : "settled")
225	                            + " without a proof.");
226	        }
227	        if (next == ClaimStatus.SETTLED && !review && aboveClerkLimit(sheetId, user, settling)) {
228	            next = ClaimStatus.PENDING;
229	            settling = null;
230	        }
231	        claim.setStatus(next);
232	        if (next == ClaimStatus.OPEN && !review) {
233	            claim.setNumber(sheets.nextClaimNumber(sheetId, claim.getDate()));
234	            claim.setOpenedBy(user);
235	        } else if (next == ClaimStatus.SETTLED) {
236	            claim.setSettledDue(settling);
237	        }
238	        logStatus(sheetId, user, person, claim);
239	        Claim saved = claims.saveAndFlush(claim);
240	        String event = switch (next) {
241	            case OPEN -> review ? "CLAIM_REJECTED" : "CLAIM_OPENED";
242	            case PENDING -> "CLAIM_PENDING";
243	            case SETTLED -> review ? "CLAIM_APPROVED" : "CLAIM_SETTLED";
244	            case VOID -> "CLAIM_VOIDED";
245	            case DRAFT -> throw new IllegalStateException();
246	        };
247	        audit.recordOnCommit(record(event, sheetId, user, person, saved)
248	                + (saved.getNumber() != null ? " number=" + saved.getNumber() : "")
249	                + (next == ClaimStatus.SETTLED ? " due=" + dueText(saved.getSettledDue()) : "")
250	                + (reason != null ? " reason=" + reason : ""));
251	        rollup.recordChanges(sheetId, user, before);
252	        return saved;
253	    }
254	
255	    /**
256	     * Defer an OPEN claim until a date after the sheet's today: until the sheet's today reaches it
257	     * the claim counts in no total, is not overdue and cannot be settled; a statement it is bound
258	     * by stays as it is. Refused (409) for a claim that is not OPEN, (400) for a date
259	     * not after the sheet's today and (423) when dated inside a closed period.
260	     */
261	    @Transactional
262	    public Claim defer(String sheetId, String user, long id, LocalDate until) {
263	        roles.refuseViewer(sheetId, user);
264	        RollupService.Snapshot before = rollup.snapshot(sheetId);
265	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
266	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet."));
267	        if (claim.getStatus() != ClaimStatus.OPEN) {
268	            throw new ResponseStatusException(HttpStatus.CONFLICT,
269	                    "A " + claim.getStatus() + " claim cannot be deferred.");
270	        }
271	        if (!until.isAfter(sheets.today(sheetId))) {
272	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
273	                    "A claim can only be deferred to a date after the sheet's today.");
274	        }
275	        periods.refuseIfClosed(sheetId, claim.getDate());
276	        Person person = person(sheetId, claim.getPersonId());
277	        claim.setDeferredUntil(until);
278	        Claim saved = claims.saveAndFlush(claim);
279	        audit.recordOnCommit(record("CLAIM_DEFERRED", sheetId, user, person, saved)
280	                + (saved.getNumber() != null ? " number=" + saved.getNumber() : "") + " until=" + until);
281	        rollup.recordChanges(sheetId, user, before);
282	        return saved;
283	    }
284	
285	    /**
286	     * Raise a claim's proofs count by one. Refused (409) for a SETTLED or VOID claim and (423) when
287	     * dated inside a closed period.
288	     */
289	    @Transactional
290	    public Claim addProof(String sheetId, String user, long id) {
291	        roles.refuseViewer(sheetId, user);
292	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
293	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet."));
294	        if (claim.getStatus() == ClaimStatus.SETTLED || claim.getStatus() == ClaimStatus.VOID) {
295	            throw new ResponseStatusException(HttpStatus.CONFLICT,
296	                    "A " + claim.getStatus() + " claim cannot have a proof added.");
297	        }
298	        periods.refuseIfClosed(sheetId, claim.getDate());
299	        Person person = person(sheetId, claim.getPersonId());
300	        claim.addProof();
301	        Claim saved = claims.saveAndFlush(claim);
302	        audit.recordOnCommit(record("CLAIM_PROOF_ADDED", sheetId, user, person, saved)
303	                + (saved.getNumber() != null ? " number=" + saved.getNumber() : "") + " proofs=" + saved.getProofs());
304	        return saved;
305	    }
306	
307	    /**
308	     * Re-settle a SETTLED claim: fix its due again at the figure it would have on the sheet's today
309	     * as an open claim bound by no statement, with its late charge. Refused (403) for anyone but a
310	     * steward, (409) for a claim that is not SETTLED and (423) when dated inside a closed period.
311	     */
312	    @Transactional
313	    public Claim resettle(String sheetId, String user, long id) {
314	        roles.refuseViewer(sheetId, user);
315	        if (!isSteward(sheetId, user)) {
316	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward can re-settle a claim.");
317	        }
318	        RollupService.Snapshot before = rollup.snapshot(sheetId);
319	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
320	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet."));
321	        if (claim.getStatus() != ClaimStatus.SETTLED) {
322	            throw new ResponseStatusException(HttpStatus.CONFLICT,
323	                    "A " + claim.getStatus() + " claim cannot be re-settled.");
324	        }
325	        periods.refuseIfClosed(sheetId, claim.getDate());
326	        Person person = person(sheetId, claim.getPersonId());
327	        BigDecimal old = claim.getSettledDue();
328	        BigDecimal settling = LateCharge.withChargeAsOpen(sheets.sheet(sheetId), claim, due(sheetId, person, claim));
329	        claim.setSettledDue(settling);
330	        logStatus(sheetId, user, person, claim);
331	        Claim saved = claims.saveAndFlush(claim);
332	        audit.recordOnCommit(record("CLAIM_RESETTLED", sheetId, user, person, saved)
333	                + (saved.getNumber() != null ? " number=" + saved.getNumber() : "")
334	                + " old=" + dueText(old) + " new=" + dueText(settling));
335	        rollup.recordChanges(sheetId, user, before);
336	        return saved;
337	    }
338	
339	    /**
340	     * Move a DRAFT, OPEN or PENDING claim to another person on the sheet. It keeps its number and
341	     * date, is unbound from any statement (live again until its new person's next statement), and
342	     * is listed first under its new person. Refused (403) for a role the permission matrix does not allow, (409) for a SETTLED or VOID
343	     * claim or a move to the person it is already on, (400) for a correction (it must stay with
344	     * the claim it corrects), (423) when dated inside a closed period and (422) when dated after
345	     * the new person's retirement date.
346	     */
347	    @Transactional
348	    public Claim reassign(String sheetId, String user, long id, long toPersonId) {
349	        roles.refuseUnlessPermitted(sheetId, user, "reassign");
350	        RollupService.Snapshot before = rollup.snapshot(sheetId);
351	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
352	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet."));
353	        if (claim.getStatus() == ClaimStatus.SETTLED || claim.getStatus() == ClaimStatus.VOID) {
354	            throw new ResponseStatusException(HttpStatus.CONFLICT,
355	                    "A " + claim.getStatus() + " claim cannot be moved.");
356	        }
357	        Person from = person(sheetId, claim.getPersonId());
358	        Person to = person(sheetId, toPersonId);
359	        if (from.getId().equals(to.getId())) {
360	            throw new ResponseStatusException(HttpStatus.CONFLICT, "That claim is already on that person.");
361	        }
362	        if (claim.isCorrection()) {
363	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A correction cannot be moved.");
364	        }
365	        periods.refuseIfClosed(sheetId, claim.getDate());
366	        refuseIfRetired(to, claim.getDate());
367	        claim.setPersonId(to.getId());
368	        claim.bind(false, null);
369	        claims.saveAndFlush(claim);
370	        claims.listFirst(claim.getId());
371	        Claim saved = claims.findByIdAndSheetId(id, sheetId).orElseThrow();
372	        audit.recordOnCommit(record("CLAIM_REASSIGNED", sheetId, user, to, saved)
373	                + (saved.getNumber() != null ? " number=" + saved.getNumber() : "")
374	                + " from=" + from.getName() + " to=" + to.getName());
375	        rollup.recordChanges(sheetId, user, before);
376	        return saved;
377	    }
378	
379	    /** What a bulk open did: how many claims were opened and how many refused, and the claims opened. */
380	    public record BulkOpened(int opened, int refused, List<Claim> claims) {
381	    }
382	
383	    /**
384	     * Open the given claims together, in list order (the order people were added, newest claim
385	     * first within a person), so they are numbered in that order. A claim that cannot be opened
386	     * (not on the sheet, not DRAFT, or dated inside a closed period) is refused and left as it is.
387	     */
388	    @Transactional
389	    public BulkOpened bulkOpen(String sheetId, String user, Collection<Long> ids) {
390	        List<Claim> selected = inListOrder(sheetId, ids);
391	        int refused = (int) ids.stream().distinct().count() - selected.size();
392	        List<Claim> opened = new ArrayList<>();
393	        boolean permitted = sheets.sheet(sheetId).permits("open", roles.roleOf(sheetId, user));
394	        for (Claim claim : selected) {
395	            if (!permitted || claim.getStatus() != ClaimStatus.DRAFT || periods.isClosed(sheetId, claim.getDate())) {
396	                refused++;
397	                continue;
398	            }
399	            opened.add(changeStatus(sheetId, user, claim.getId(), ClaimStatus.OPEN));
400	        }
401	        return new BulkOpened(opened.size(), refused, opened);
402	    }
403	
404	    /** What a bulk settle did: how many claims were settled (or made PENDING) and how many refused, and the claims changed. */
405	    public record BulkSettled(int settled, int refused, List<Claim> claims) {
406	    }
407	
408	    /**
409	     * Settle the given claims together, in list order (the order people were added, newest claim
410	     * first within a person), each by exactly the rules of settling one claim. A claim a clerk's
411	     * settle makes PENDING counts as settled; a claim that cannot be settled is refused and left
412	     * as it is.
413	     */
414	    @Transactional
415	    public BulkSettled bulkSettle(String sheetId, String user, Collection<Long> ids) {
416	        List<Claim> selected = inListOrder(sheetId, ids);
417	        int refused = (int) ids.stream().distinct().count() - selected.size();
418	        List<Claim> settled = new ArrayList<>();
419	        for (Claim claim : selected) {
420	            try {
421	                settled.add(changeStatus(sheetId, user, claim.getId(), ClaimStatus.SETTLED));
422	            } catch (ResponseStatusException refusedOne) {
423	                // every refusal is checked before the claim is changed, so it is left as it is
424	                refused++;
425	            }
426	        }
427	        return new BulkSettled(settled.size(), refused, settled);
428	    }
429	
430	    /** The given claims on the sheet in list order: people as added, newest claim first within a person. */
431	    private List<Claim> inListOrder(String sheetId, Collection<Long> ids) {
432	        Map<Long, Integer> personOrder = new HashMap<>();
433	        List<Person> listed = people.findBySheetIdOrderByIdAsc(sheetId);
434	        for (int i = 0; i < listed.size(); i++) {
435	            personOrder.put(listed.get(i).getId(), i);
436	        }
437	        return ids.stream().distinct()
438	                .flatMap(id -> claims.findByIdAndSheetId(id, sheetId).stream())
439	                .sorted(Comparator.<Claim>comparingInt(c -> personOrder.getOrDefault(c.getPersonId(), Integer.MAX_VALUE))
440	                        .thenComparing(Claim::getListed, Comparator.reverseOrder()))
441	                .toList();
442	    }
443	
444	    /**
445	     * The due on a claim's amount at the rate for the person's grade in force on the claim's date,
446	     * rounded to the cent as the claim rounds (see {@link Rounding}) and raised to the floor in force on the claim's date (a correction's is not); null with no
447	     * rate in force then.
448	     */
449	    public BigDecimal due(String sheetId, Person person, Claim claim) {
450	        Sheet sheet = sheets.sheet(sheetId);
451	        RoundingMode rounding = Rounding.mode(sheet, roundingDate(sheetId, claim));
452	        return rates.findInForce(sheetId, person.gradeOn(claim.getDate()), claim.getDate()).map(Rate::getPct)
453	                .map(pct -> claim.getAmount().multiply(pct).divide(BigDecimal.valueOf(100), 2, rounding))
454	                .map(due -> claim.isCorrection() ? due : due.max(sheet.floorOn(claim.getDate())))
455	                .orElse(null);
456	    }
457	
458	    /** The date a claim rounds by: its own, or for a correction that of the claim it corrects. */
459	    private LocalDate roundingDate(String sheetId, Claim claim) {
460	        if (!claim.isCorrection() || claim.getCorrects() == null) {
461	            return claim.getDate();
462	        }
463	        return Rounding.dateOf(claim, claims.findBySheetIdAndPersonIdOrderByIdDesc(sheetId, claim.getPersonId()));
464	    }
465	
466	    /** Log the claim's status as it is now: by the user, on the sheet's today, with its due as computed now. */
467	    private void logStatus(String sheetId, String user, Person person, Claim claim) {
468	        claim.log(new ClaimLogEntry(claim.getStatus(), user, sheets.today(sheetId),
469	                dueText(charged(sheetId, person, claim))));
470	    }
471	
472	    private static String dueText(BigDecimal due) {
473	        return due == null ? "n/a" : due.setScale(2, RoundingMode.UNNECESSARY).toPlainString();
474	    }
475	
476	    /** Whether a claim settling at the figure is above the proof threshold in force on its date and has no proofs. */
477	    private boolean needsProof(String sheetId, Claim claim, BigDecimal figure) {
478	        BigDecimal threshold = sheets.sheet(sheetId).proofThresholdOn(claim.getDate());
479	        return claim.getProofs() == 0 && figure != null && threshold != null && figure.compareTo(threshold) > 0;
480	    }
481	
482	    /** Whether the user is a clerk settling a claim whose figure is above the sheet's clerk limit. */
483	    private boolean aboveClerkLimit(String sheetId, String user, BigDecimal figure) {
484	        BigDecimal limit = sheets.clerkLimit(sheetId);
485	        return figure != null && limit != null && figure.compareTo(limit) > 0 && !isSteward(sheetId, user);
486	    }
487	
488	    private boolean isSteward(String sheetId, String user) {
489	        return Role.STEWARD.equals(roles.roleOf(sheetId, user));
490	    }
491	
492	    /**
493	     * The number a claim corrects: none unless its amount is negative, when it must name the number
494	     * of a SETTLED claim of the same person, else it is refused (400).
495	     */
496	    private String corrected(String sheetId, long personId, BigDecimal amount, String corrects) {
497	        if (amount.signum() >= 0) {
498	            return null;
499	        }
500	        boolean settled = corrects != null && claims.findBySheetIdAndPersonIdOrderByIdDesc(sheetId, personId).stream()
501	                .anyMatch(c -> corrects.equals(c.getNumber()) && c.getStatus() == ClaimStatus.SETTLED);
502	        if (!settled) {
503	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
504	                    "A negative amount must correct a SETTLED claim of the same person, by its number.");
505	        }
506	        return corrects;
507	    }
508	
509	    /** Refuse (422) a claim dated after its person's retirement date. */
510	    private static void refuseIfRetired(Person person, LocalDate date) {
511	        if (person.isRetired() && date.isAfter(person.getRetiredFrom())) {
512	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,
513	                    "That claim's date is after its person's retirement date.");
514	        }
515	    }
516	
517	    private Person person(String sheetId, long personId) {
518	        return people.findByIdAndSheetId(personId, sheetId)
519	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet."));
520	    }
521	
522	    private static String record(String event, String sheetId, String user, Person person, Claim claim) {
523	        return event + " sheet=" + sheetId + " by=" + user + " person=" + person.getName() + " amount="
524	                + claim.getAmount().setScale(2, RoundingMode.UNNECESSARY).toPlainString() + " date=" + claim.getDate();
525	    }
526	
527	    private LocalDate dateOrToday(String sheetId, LocalDate date) {
528	        return date != null ? date : sheets.today(sheetId);
529	    }
530	}
