1	import { HttpClient, HttpErrorResponse } from '@angular/common/http';
2	import { Component, computed, inject, input, output, signal } from '@angular/core';
3	import { firstValueFrom } from 'rxjs';
4	import { Session } from '../../core/session';
5	import { Period, inClosedPeriod, periodOn } from '../periods/periods';
6	import { DatedGrade, DatedValue, Lateness, Rate, chargedDueCents, dueText, gradeOn } from '../rates/rates';
7	
8	// A person's claims, newest first, and the one form under their row that both adds a claim and
9	// edits an existing one (opening a claim's editor fills the form with its values). Each claim
10	// shows its status and the buttons that move it on; a move its status does not allow is refused
11	// with an error on the claim, as is the user who opened a claim settling it (four eyes). A claim
12	// dated inside a closed period cannot be added, edited or moved on: each is refused with an error.
13	// Only a DRAFT can be edited; editing any other claim is refused with an error on the claim (to
14	// change an open claim, void it and add a new one).
15	// Each claim shows its due-by, fixed when it was added (its date plus the terms of its person's grade
16	// in force on its date, or the sheet's terms when that grade has none), and whether it is overdue:
17	// OPEN with its due-by before the sheet's today. An overdue claim's due gains the sheet's late
18	// percent of its figure for every full 30 days it is overdue.
19	// A claim with a negative amount is a correction: it must name, by number, a SETTLED claim of the
20	// same person that it corrects, else it is refused. Its due has no floor and no late charge, and
21	// it shows the number it corrects.
22	// A clerk settling a claim whose due is above the clerk limit makes it PENDING. A PENDING claim
23	// counts like an OPEN one but is not bound by a statement: it shows its live figure. A steward
24	// approves it (SETTLED, its due fixed then) or rejects it with a reason (back to OPEN, bound again
25	// by the last statement); the user who opened it cannot approve it.
26	// Who may open, settle, void or move a claim is the sheet's permission matrix (see the settings).
27	// By default a steward can move a DRAFT, OPEN or PENDING claim to another person: it keeps its number and
28	// date, loses any figure a statement bound it to, and is listed first under its new person.
29	// An OPEN claim can be deferred to a date after the sheet's today (refused for a claim that is not
30	// OPEN, a date not after today, or a claim in a closed period). Until the sheet's today reaches that
31	// date it counts in no total, is not overdue, cannot be settled and is left unbound by a statement.
32	// Each claim shows its proofs count, raised by one with its proof button (refused for a SETTLED or
33	// VOID claim, or one in a closed period). A claim whose due is above the proof threshold in force on
34	// its date cannot be settled or approved while it has no proofs: refused with an error on the claim.
35	export type ClaimStatus = 'DRAFT' | 'OPEN' | 'PENDING' | 'SETTLED' | 'VOID';
36	
37	export interface Claim {
38	  id: number;
39	  personId: number;
40	  amount: string;
41	  date: string;
42	  note: string;
43	  status: ClaimStatus;
44	  /** The claim's number on the sheet, given when opened; null while DRAFT. Sheet-wide (1, 2, ...), or
45	   *  under numbering per period <period name>-<n>, or X-<n> in no period. */
46	  number: string | null;
47	  /** The due fixed when the claim was settled; null while not settled or if its grade then had no rate. */
48	  settledDue: string | null;
49	  /** The user who opened the claim; null while DRAFT, or if voided without being opened. */
50	  openedBy: string | null;
51	  /** Whether the person's last statement bound the claim to the figure it had then. */
52	  stated: boolean;
53	  /** The figure bound by the last statement; null while unbound or if it had no rate then. */
54	  statedDue: string | null;
55	  /** The number of the claim this correction corrects; null for a claim that is not a correction. */
56	  corrects: string | null;
57	  /** The date the claim is due by, fixed when it was added. */
58	  dueBy: string;
59	  /** The claim's status log, oldest first: who moved it to each status, on the sheet's today then,
60	   *  with its due as computed at that moment. */
61	  log: ClaimLogLine[];
62	  /** The date the claim is deferred until; null when it was never deferred. */
63	  deferredUntil: string | null;
64	  /** How many proofs the claim has. */
65	  proofs: number;
66	}
67	
68	/** One line of a claim's status log. */
69	export interface ClaimLogLine {
70	  status: ClaimStatus;
71	  by: string;
72	  date: string;
73	  due: string;
74	}
75	
76	/** The date a claim's live figures round by: its own, or for a correction the date of the claim it
77	 *  corrects, found by number among `claims` (its own when that claim is not among them). */
78	export function roundingDate(c: Claim, claims: readonly Claim[]): string {
79	  if (!isCorrection(c) || c.corrects === null) return c.date;
80	  return claims.find((o) => o.number === c.corrects)?.date ?? c.date;
81	}
82	
83	/** Whether a claim is a correction: its amount is below zero. */
84	export function isCorrection(c: Claim): boolean {
85	  return cents(c.amount) < 0;
86	}
87	
88	/** Another person a claim can be moved to. */
89	export interface ClaimTarget {
90	  id: number;
91	  name: string;
92	}
93	
94	/** A move from one status to the next, by the endpoint that makes it. */
95	type ClaimAction = 'open' | 'settle' | 'resettle' | 'approve' | 'reject' | 'void';
96	
97	/** Whether a claim counts toward claimed, due-total and every total: only OPEN, PENDING and SETTLED do. */
98	export function counts(c: Claim): boolean {
99	  return isOpen(c) || c.status === 'SETTLED';
100	}
101	
102	/** The status a claim had at the end of a day (yyyy-mm-dd), as its status log records it (the last
103	 *  line logged on or before it); null when it had none yet. */
104	export function statusAt(c: Claim, day: string): ClaimStatus | null {
105	  let at: ClaimStatus | null = null;
106	  for (const l of c.log) if (l.date <= day) at = l.status;
107	  return at;
108	}
109	
110	/** Whether a claim is open: OPEN or PENDING. Only an open claim goes overdue, and a hold takes it out of the totals. */
111	export function isOpen(c: Claim): boolean {
112	  return c.status === 'OPEN' || c.status === 'PENDING';
113	}
114	
115	/** Whether a claim is deferred on the sheet's today: open, and its deferral date not yet reached. */
116	export function deferred(c: Claim, today: string | null): boolean {
117	  return isOpen(c) && c.deferredUntil !== null && today !== null && today < c.deferredUntil;
118	}
119	
120	/** The refusal of a change to a claim dated inside a closed period. */
121	const CLOSED = 'That date is inside a closed period.';
122	
123	/** The refusal of a correction that names no SETTLED claim of its person. */
124	const UNCORRECTABLE = 'A negative amount must correct a SETTLED claim of this person, by its number.';
125	
126	const PAST: Record<ClaimAction, string> = {
127	  open: 'opened',
128	  settle: 'settled',
129	  resettle: 're-settled',
130	  approve: 'approved',
131	  reject: 'rejected',
132	  void: 'voided',
133	};
134	
135	/** A reason for rejecting a claim: one word. */
136	const REASON = /^\S{1,200}$/;
137	
138	/** An amount: 0.00 or more, with up to two decimals. */
139	export const AMOUNT = /^\d{1,12}(\.\d{1,2})?$/;
140	
141	/** A claim's amount: as {@link AMOUNT}, or below zero for a correction. */
142	const SIGNED_AMOUNT = /^-?\d{1,12}(\.\d{1,2})?$/;
143	
144	/** A claim number: a whole number from 1, or a period's (or X) with its number in it, as <name>-<n>. */
145	const NUMBER = /^(.{1,100}-)?[1-9]\d{0,8}$/;
146	
147	/** An amount in whole cents, so sums are exact; below zero for a negative amount. */
148	export function cents(amount: string): number {
149	  const negative = amount.startsWith('-');
150	  const [whole, frac = ''] = (negative ? amount.slice(1) : amount).split('.');
151	  const c = Number(whole) * 100 + Number(frac.padEnd(2, '0'));
152	  return negative ? -c : c;
153	}
154	
155	/** Days since 1970-01-01 of a yyyy-mm-dd date (proleptic Gregorian). */
156	function dayNumber(date: string): number {
157	  const [y0, m, d] = date.split('-').map(Number);
158	  const y = m <= 2 ? y0 - 1 : y0;
159	  const era = Math.floor(y / 400);
160	  const yoe = y - era * 400;
161	  const doy = Math.floor((153 * (m + (m > 2 ? -3 : 9)) + 2) / 5) + d - 1;
162	  const doe = yoe * 365 + Math.floor(yoe / 4) - Math.floor(yoe / 100) + doy;
163	  return era * 146097 + doe - 719468;
164	}
165	
166	/** The yyyy-mm-dd date a number of days after a yyyy-mm-dd date (proleptic Gregorian). */
167	export function plusDays(date: string, days: number): string {
168	  const z = dayNumber(date) + days + 719468;
169	  const era = Math.floor(z / 146097);
170	  const doe = z - era * 146097;
171	  const yoe = Math.floor((doe - Math.floor(doe / 1460) + Math.floor(doe / 36524) - Math.floor(doe / 146096)) / 365);
172	  const doy = doe - (365 * yoe + Math.floor(yoe / 4) - Math.floor(yoe / 100));
173	  const mp = Math.floor((5 * doy + 2) / 153);
174	  const d = doy - Math.floor((153 * mp + 2) / 5) + 1;
175	  const m = mp < 10 ? mp + 3 : mp - 9;
176	  const y = yoe + era * 400 + (m <= 2 ? 1 : 0);
177	  return `${String(y).padStart(4, '0')}-${String(m).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
178	}
179	
180	/** The date a claim is due by: fixed when it was added. */
181	export function dueBy(c: Claim): string {
182	  return c.dueBy;
183	}
184	
185	/** Whether a claim is overdue: open (OPEN or PENDING), not deferred, and due by a date before the sheet's today. */
186	export function overdue(c: Claim, today: string | null): boolean {
187	  return isOpen(c) && !deferred(c, today) && today !== null && dueBy(c) < today;
188	}
189	
190	/** The days a claim is overdue on the sheet's today: past its due-by; 0 when it is not overdue. */
191	export function daysOverdue(c: Claim, today: string | null): number {
192	  return overdue(c, today) && today !== null ? dayNumber(today) - dayNumber(dueBy(c)) : 0;
193	}
194	
195	/** Whole cents shown with two decimals, with a minus sign below zero. */
196	export function money(c: number): string {
197	  const a = Math.abs(c);
198	  return `${c < 0 ? '-' : ''}${Math.floor(a / 100)}.${String(a % 100).padStart(2, '0')}`;
199	}
