282	          />
283	          <button type="button" data-testid="claim-reject" (click)="act(c, 'reject')">Reject</button>
284	          <button type="button" data-testid="claim-proof" (click)="addProof(c)">Add proof</button>
285	          <button type="button" data-testid="claim-void" (click)="act(c, 'void')">Void</button>
286	          <label [for]="'claim-defer-date-' + c.id">Defer until</label>
287	          <input
288	            [id]="'claim-defer-date-' + c.id"
289	            type="date"
290	            data-testid="claim-defer-date"
291	            [value]="deferDates().get(c.id) ?? ''"
292	            (input)="setDeferDate(c.id, $any($event.target).value)"
293	          />
294	          <button type="button" data-testid="claim-defer" (click)="defer(c)">Defer</button>
295	          <label [for]="'claim-reassign-to-' + c.id">Move to</label>
296	          <select
297	            [id]="'claim-reassign-to-' + c.id"
298	            data-testid="claim-reassign-to"
299	            (change)="setTarget(c.id, $any($event.target).value)"
300	          >
301	            <option value="" [selected]="!targets().get(c.id)">Choose a person</option>
302	            @for (o of others(); track o.id) {
303	              <option [value]="o.id" [selected]="targets().get(c.id) === '' + o.id">{{ o.name }}</option>
304	            }
305	          </select>
306	          <button type="button" data-testid="claim-reassign" (click)="reassign(c)">Move</button>
307	          <button
308	            type="button"
309	            data-testid="claim-edit"
310	            [attr.aria-label]="'Edit claim of ' + c.amount + ' on ' + c.date"
311	            (click)="edit(c)"
312	          >
313	            Edit
314	          </button>
315	          @if (editingId() === c.id) {
316	            <button type="button" data-testid="claim-cancel" (click)="reset()">Cancel</button>
317	          }
318	          @if (actionErrors().get(c.id); as err) {
319	            <p role="alert" data-testid="claim-error">{{ err }}</p>
320	          }
321	        </li>
322	      }
323	    </ul>
324	  `,
325	})
326	export class PersonClaims {
327	  private readonly http = inject(HttpClient);
328	  private readonly session = inject(Session);
329	
330	  readonly personId = input.required<number>();
331	  readonly personName = input.required<string>();
332	  readonly claims = input.required<Claim[]>();
333	  /** The person's grades: the one in force on a claim's date, at its rate then, gives what the claim has due. */
334	  readonly grades = input.required<DatedGrade[]>();
335	  /** The sheet's rates. */
336	  readonly rates = input.required<Rate[]>();
337	  /** The sheet's floors, dated: the one in force on a claim's date is the least its live due can be. */
338	  readonly floors = input.required<DatedValue[]>();
339	  /** The sheet's late percents, dated: for each full 30 days a claim is overdue, the one in force on
340	   *  that boundary date (its due-by plus 30, 60, 90 ... days) is what it gains of its figure. */
341	  readonly latePcts = input.required<DatedValue[]>();
342	  /** The sheet's policy date (blank: its today): a claim dated before it rounds half up, else half to even. */
343	  readonly policyDate = input.required<string>();
344	  /** The sheet's periods. */
345	  readonly periods = input.required<Period[]>();
346	  /** The ids of the claims selected for a bulk action, across the sheet. */
347	  readonly selected = input.required<ReadonlySet<number>>();
348	  /** The sheet's people, by id and name: a claim can be moved to any of them but its own. */
349	  readonly people = input.required<ClaimTarget[]>();
350	  readonly saved = output<Claim>();
351	  /** A claim moved to another person: it is listed first under them. */
352	  readonly reassigned = output<Claim>();
353	  /** A claim's checkbox ticked (on) or cleared. */
354	  readonly selectedChange = output<{ id: number; on: boolean }>();
355	
356	  protected readonly amountInput = signal('');
357	  protected readonly dateInput = signal('');
358	  protected readonly noteInput = signal('');
359	  protected readonly correctsInput = signal('');
360	  protected readonly editingId = signal<number | null>(null);
361	  protected readonly error = signal<string | null>(null);
362	  /** Whether a submit is waiting for its answer: a second submit meanwhile is ignored. */
363	  private submitting = false;
364	  /** The error of each claim's last refused status change, by claim id. */
365	  protected readonly actionErrors = signal<ReadonlyMap<number, string>>(new Map());
366	  /** The reason typed for rejecting each claim, by claim id. */
367	  protected readonly reasons = signal<ReadonlyMap<number, string>>(new Map());
368	  /** The date typed to defer each claim until, by claim id. */
369	  protected readonly deferDates = signal<ReadonlyMap<number, string>>(new Map());
370	  /** The person id chosen to move each claim to, by claim id. */
371	  protected readonly targets = signal<ReadonlyMap<number, string>>(new Map());
372	  /** The people a claim of this person can be moved to. */
373	  protected readonly others = computed(() => this.people().filter((p) => p.id !== this.personId()));
374	
375	  /** A stated claim shows the figure bound by the last statement, a settled claim the due fixed
376	   *  when it was settled; any other claim's due is live, at the rate for the person's grade in
377	   *  force on the claim's date (the grade in force then), never below the floor in force on its date. An overdue claim's late charge is
378	   *  added on top. */
379	  protected dueOf(c: Claim): string {
380	    const late: Lateness = {
381	      latePcts: this.latePcts(),
382	      today: this.session.today(),
383	      policyDate: this.policyDate(),
384	    };
385	    const roundOn = roundingDate(c, this.claims());
386	    return dueText(chargedDueCents(c, this.rates(), gradeOn(this.grades(), c.date), this.floors(), late, roundOn));
387	  }
388	
389	  protected dueByOf(c: Claim): string {
390	    return dueBy(c);
391	  }
392	
393	  protected overdueOf(c: Claim): boolean {
394	    return overdue(c, this.session.today());
395	  }
396	
397	  protected deferredOf(c: Claim): boolean {
398	    return deferred(c, this.session.today());
399	  }
400	
401	  /** The name of the period whose dates contain the claim's date; blank when none does. */
402	  protected periodOf(c: Claim): string {
403	    return periodOn(this.periods(), c.date)?.name ?? '';
404	  }
405	
406	  protected edit(c: Claim): void {
407	    this.clearActionError(c.id);
408	    if (inClosedPeriod(this.periods(), c.date)) {
409	      this.actionErrors.update((m) => new Map(m).set(c.id, CLOSED));
410	      return;
411	    }
412	    if (c.status !== 'DRAFT') {
413	      this.actionErrors.update((m) => new Map(m).set(c.id, `A ${c.status} claim cannot be edited.`));
414	      return;
415	    }
416	    this.editingId.set(c.id);
417	    this.amountInput.set(c.amount);
418	    this.dateInput.set(c.date);
419	    this.noteInput.set(c.note);
420	    this.correctsInput.set(c.corrects ?? '');
421	    this.error.set(null);
422	  }
423	
424	  protected reset(): void {
425	    this.editingId.set(null);
426	    this.amountInput.set('');
427	    this.dateInput.set('');
428	    this.noteInput.set('');
429	    this.correctsInput.set('');
430	    this.error.set(null);
431	  }
432	
433	  private clearActionError(id: number): void {
434	    this.actionErrors.update((m) => {
435	      if (!m.has(id)) return m;
436	      const next = new Map(m);
437	      next.delete(id);
438	      return next;
439	    });
440	  }
441	
442	  protected setReason(id: number, reason: string): void {
443	    this.reasons.update((m) => new Map(m).set(id, reason));
444	    this.clearActionError(id);
445	  }
446	
447	  protected setTarget(id: number, personId: string): void {
448	    this.targets.update((m) => new Map(m).set(id, personId));
449	    this.clearActionError(id);
450	  }
451	
452	  protected setDeferDate(id: number, date: string): void {
453	    this.deferDates.update((m) => new Map(m).set(id, date));
454	    this.clearActionError(id);
455	  }
456	
457	  /** Defer an OPEN claim until the date typed; the server refuses any other claim, a date not after
458	   *  the sheet's today, and a claim dated inside a closed period. */
459	  protected async defer(c: Claim): Promise<void> {
460	    this.clearActionError(c.id);
461	    const sheet = this.session.sheet();
462	    const until = (this.deferDates().get(c.id) ?? '').trim();
463	    if (!/^\d{4}-\d{2}-\d{2}$/.test(until)) {
464	      this.actionErrors.update((m) => new Map(m).set(c.id, 'Enter the date to defer this claim until.'));
465	      return;
466	    }
467	    try {
468	      const claim = await firstValueFrom(
469	        this.http.post<Claim>('/api/claims/defer', { sheet, user: this.session.user(), id: c.id, until }),
470	      );
471	      if (this.session.sheet() !== sheet) return;
472	      this.saved.emit(claim);
473	    } catch (e) {
474	      if (this.session.sheet() !== sheet) return;
475	      const status = e instanceof HttpErrorResponse ? e.status : 0;
476	      const err =
477	        status === 423
478	          ? CLOSED
479	          : status === 400
480	            ? 'A claim can only be deferred to a date after the sheet\'s today.'
481	            : status === 409
482	              ? `A ${c.status} claim cannot be deferred.`
483	              : 'Could not defer this claim.';
484	      this.actionErrors.update((m) => new Map(m).set(c.id, err));
485	    }
486	  }
487	
488	  /** Move a claim to the chosen person; the server refuses a clerk, and a SETTLED or VOID claim. */
489	  protected async reassign(c: Claim): Promise<void> {
490	    this.clearActionError(c.id);
491	    const sheet = this.session.sheet();
492	    const personId = Number(this.targets().get(c.id) ?? '');
493	    if (!personId) {
494	      this.actionErrors.update((m) => new Map(m).set(c.id, 'Choose the person to move this claim to.'));
495	      return;
496	    }
497	    try {
498	      const claim = await firstValueFrom(
499	        this.http.post<Claim>('/api/claims/reassign', { sheet, user: this.session.user(), id: c.id, personId }),
500	      );
501	      if (this.session.sheet() !== sheet) return;
502	      this.targets.update((m) => {
503	        const next = new Map(m);
504	        next.delete(c.id);
505	        return next;
506	      });
507	      this.reassigned.emit(claim);
508	    } catch (e) {
509	      if (this.session.sheet() !== sheet) return;
510	      const status = e instanceof HttpErrorResponse ? e.status : 0;
511	      const err =
512	        status === 403
513	          ? 'Your role may not move a claim on this sheet.'
514	          : status === 423
515	            ? CLOSED
516	            : status === 422
517	              ? 'A claim cannot be moved to a person retired before its date.'
518	              : status === 400
519	                ? 'A correction cannot be moved.'
520	                : status === 409 && (c.status === 'SETTLED' || c.status === 'VOID')
521	                  ? `A ${c.status} claim cannot be moved.`
522	                  : 'Could not move this claim.';
523	      this.actionErrors.update((m) => new Map(m).set(c.id, err));
524	    }
525	  }
526	
527	  /** Raise a claim's proofs count by one; the server refuses a SETTLED or VOID claim, and one dated
528	   *  inside a closed period. */
529	  protected async addProof(c: Claim): Promise<void> {
530	    this.clearActionError(c.id);
531	    const sheet = this.session.sheet();
532	    try {
533	      const claim = await firstValueFrom(
534	        this.http.post<Claim>('/api/claims/proof', { sheet, user: this.session.user(), id: c.id }),
535	      );
536	      if (this.session.sheet() !== sheet) return;
537	      this.saved.emit(claim);
538	    } catch (e) {
539	      if (this.session.sheet() !== sheet) return;
540	      const status = e instanceof HttpErrorResponse ? e.status : 0;
541	      const err =
542	        status === 423
543	          ? CLOSED
544	          : status === 409
545	            ? `A ${c.status} claim cannot have a proof added.`
546	            : 'Could not add a proof to this claim.';
547	      this.actionErrors.update((m) => new Map(m).set(c.id, err));
548	    }
549	  }
550	
551	  /** Move a claim to its next status; the server refuses a move its status does not allow. */
552	  protected async act(c: Claim, action: ClaimAction): Promise<void> {
553	    this.clearActionError(c.id);
554	    const sheet = this.session.sheet();
555	    const reason = (this.reasons().get(c.id) ?? '').trim();
556	    if (action === 'reject' && !REASON.test(reason)) {
557	      this.actionErrors.update((m) => new Map(m).set(c.id, 'Enter a one-word reason to reject this claim.'));
558	      return;
559	    }
560	    const body = { sheet, user: this.session.user(), id: c.id, ...(action === 'reject' ? { reason } : {}) };
561	    try {
562	      const claim = await firstValueFrom(this.http.post<Claim>(`/api/claims/${action}`, body));
563	      if (this.session.sheet() !== sheet) return;
564	      if (action === 'reject') this.setReason(c.id, '');
565	      this.saved.emit(claim);
566	    } catch (e) {
567	      if (this.session.sheet() !== sheet) return;
568	      const err =
569	        e instanceof HttpErrorResponse && e.status === 403
570	          ? action === 'approve' || action === 'reject'
571	            ? c.openedBy === this.session.user() && action === 'approve'
572	              ? 'The user who opened a claim cannot approve it.'
573	              : 'Only a steward can approve or reject a PENDING claim.'
574	            : action === 'resettle'
575	              ? 'Only a steward can re-settle a claim.'
576	              : action === 'settle' && c.openedBy === this.session.user()
577	                ? 'The user who opened a claim cannot settle it.'
578	                : `Your role may not ${action} a claim on this sheet.`
579	          : e instanceof HttpErrorResponse && e.status === 423
580	            ? CLOSED
581	            : e instanceof HttpErrorResponse && e.status === 422
582	              ? `This claim is due above the proof threshold and cannot be ${PAST[action]} without a proof.`
583	            : action === 'settle' && deferred(c, this.session.today())
584	              ? `This claim is deferred until ${c.deferredUntil} and cannot be settled before then.`
585	              : `A ${c.status} claim cannot be ${PAST[action]}.`;
586	      this.actionErrors.update((m) => new Map(m).set(c.id, err));
587	    }
588	  }
589	
590	  /** Whether a claim number names a SETTLED claim of this person, as a correction must. */
591	  private correctable(corrects: string): boolean {
592	    return NUMBER.test(corrects) && this.claims().some((c) => c.number === corrects && c.status === 'SETTLED');
593	  }
594	
595	  protected async save(event: Event): Promise<void> {
596	    event.preventDefault();
597	    if (this.submitting) return;
598	    this.error.set(null);
599	    const sheet = this.session.sheet();
600	    const amount = this.amountInput().trim();
601	    const date = this.dateInput().trim();
602	    const corrects = this.correctsInput().trim();
603	    if (!SIGNED_AMOUNT.test(amount)) {
604	      this.error.set('Enter an amount with up to two decimals (below zero only for a correction).');
605	      return;
606	    }
607	    const correction = cents(amount) < 0;
608	    if (correction && !this.correctable(corrects)) {
609	      this.error.set(UNCORRECTABLE);
610	      return;
611	    }
612	    if (date !== '' && !/^\d{4}-\d{2}-\d{2}$/.test(date)) {
613	      this.error.set('Enter a date, or leave it blank for the sheet\'s today.');
614	      return;
615	    }
616	    const id = this.editingId();
617	    const body = { sheet, user: this.session.user(), amount, date: date || null, note: this.noteInput().trim(),
618	      corrects: correction ? corrects : null };
619	    this.submitting = true;
620	    try {
621	      const claim =
622	        id === null
623	          ? await firstValueFrom(this.http.post<Claim>('/api/claims/add', { ...body, personId: this.personId() }))
624	          : await firstValueFrom(this.http.post<Claim>('/api/claims/update', { ...body, id }));
625	      if (this.session.sheet() !== sheet) return;
626	      this.saved.emit(claim);
627	      this.reset();
628	    } catch (e) {
629	      this.error.set(
630	        e instanceof HttpErrorResponse && e.status === 423
631	          ? CLOSED
632	          : e instanceof HttpErrorResponse && e.status === 422
633	            ? 'A claim cannot be dated after its person\'s retirement date.'
634	          : e instanceof HttpErrorResponse && e.status === 400 && correction
635	            ? UNCORRECTABLE
636	          : e instanceof HttpErrorResponse && e.status === 409
637	            ? 'Only a DRAFT claim can be edited.'
638	            : id === null
639	              ? 'Could not add this claim.'
640	              : 'Could not save this claim.',
641	      );
642	    } finally {
643	      this.submitting = false;
644	    }
645	  }
646	}

